package test

import (
	"embed"
	"io/fs"
)

//go:embed fixtures/secrets
var secretFixtures embed.FS

// SecretFixtures holds credential-shaped samples: positive/<rule-id>.txt must
// raise that rule, negative/<rule-id>.txt must not, clean.txt raises nothing.
// gitleaks/<rule-id>.json carries gitleaks' own true and false positives per
// rule, generated by its config generator at the pinned rules.json commit
// (MIT, see internal/secrets/LICENSE-gitleaks); a sample with a path is a
// file. Every credential in it is synthetic.
func SecretFixtures() fs.FS {
	sub, err := fs.Sub(secretFixtures, "fixtures/secrets")
	if err != nil {
		panic(err)
	}
	return sub
}
